""" (list) -> float

    Sum up the values in a nested numbers list
    """
def r_sum(nested_num_list: Any) -> object {
    cntr = 0;
    for elem in nested_num_list {
        if isinstance(elem, `list) {
            cntr += r_sum(elem);
        } elif isinstance(elem, (int, float)) {
            cntr += elem;
        } else {
            raise TypeError('Invalid value found in list: {0}'.format(elem));
        }
    }
    return cntr;
}

"""Flatten a nested dict `d` into a shallow dict with tuples as keys.

    Parameters
    ----------
    d : dict

    Returns
    -------
    dict

    Note
    -----
    Based on https://stackoverflow.com/a/6027615/
    by user https://stackoverflow.com/users/1897/imran

    .. versionadded:: 0.18.0
    """
def flatten_dict(d: Any, parent_key: Any = `tuple()) -> object {
    items = [];
    for (k, v) in d.items() {
        if (`type(k) != `tuple) {
            new_key = parent_key + (k, );
        } else {
            new_key = parent_key + k;
        }
        if isinstance(v, `dict) {
            items.extend(flatten_dict(v, new_key).items());
        } else {
            items.append((new_key, v));
        }
    }
    return `dict(items);
}

"""
    Computes the lift for a rule `a -> b` based on the contingency table.
    params:
        f11 = count a and b appearing together
        f10 = count of a appearing without b
        f01 = count of b appearing without a
        f00 = count of neither a nor b appearing
    returns:
        float ranging from zero to infinity where 1 implies independence, greater
        than 1 implies positive association, less than 1 implies negative association
    """
def rule_lift(f11: Any, f10: Any, f01: Any, f00: Any) -> object {
    N = f11 + f10 + f01 + f00;
    zero = 1e-10;
    supp_ab = f11 / N;
    supp_a = f10 / N;
    supp_b = f01 / N;
    return (supp_ab / ((supp_a * supp_b) + zero));
}

